-- Wilmington pilot seed: Polar Ice, its leagues and seasons, the real Fall 2026 C league
-- standings and the Hammer'd Heads totals as posted by the rink on 2026-11-05.
update teams set logo='/logos/hammerd-heads.jpg' where id=(select t.id from teams t join leagues l on l.id=t.league_id where l.level='C' and t.name='Hammer''d Heads');
